    private static final class Bridge {
        private final Activity activity;
        private final WebView scout;
        Bridge(Activity activity, WebView scout) { this.activity = activity; this.scout = scout; }

        @JavascriptInterface public void reloadScout() { activity.runOnUiThread(activity::recreate); }
        @JavascriptInterface public boolean notificationAccessEnabled() {
            try { String enabled = Settings.Secure.getString(activity.getContentResolver(), "enabled_notification_listeners"); return enabled != null && enabled.contains(activity.getPackageName()); }
            catch (Exception ignored) { return false; }
        }
        @JavascriptInterface public void openNotificationAccessSettings() { activity.runOnUiThread(() -> { try { activity.startActivity(new Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS)); } catch (Exception ignored) {} }); }
        @JavascriptInterface public String facebookNotificationCandidates() { return FacebookMarketplaceNotificationListener.rowsJson(activity); }
        @JavascriptInterface public String facebookBrowserCandidates() { return FacebookMarketplaceActivity.rowsJson(activity); }
        @JavascriptInterface public void openFacebookMarketplace(String termsJson, double lat, double lon, int radius, String postal, String url) {
            activity.runOnUiThread(() -> {
                Intent i = new Intent(activity, FacebookMarketplaceActivity.class);
                i.putExtra(FacebookMarketplaceActivity.EXTRA_TERMS, termsJson == null ? "[]" : termsJson);
                if (Double.isFinite(lat) && Double.isFinite(lon) && !(lat == 0 && lon == 0)) { i.putExtra(FacebookMarketplaceActivity.EXTRA_LAT, lat); i.putExtra(FacebookMarketplaceActivity.EXTRA_LON, lon); }
                i.putExtra(FacebookMarketplaceActivity.EXTRA_RADIUS, radius); i.putExtra(FacebookMarketplaceActivity.EXTRA_POSTAL, postal == null ? "" : postal);
                if (url != null && url.startsWith("https://www.facebook.com/marketplace/")) i.putExtra(FacebookMarketplaceActivity.EXTRA_URL, url);
                activity.startActivity(i);
            });
        }
        @JavascriptInterface public void startDeviceStockCheck(String requestId, String bodyJson) { RetailerDeviceCheckManager.check(activity, scout, requestId, bodyJson); }
        @JavascriptInterface public void openRetailerSession(String bodyJson) {
            activity.runOnUiThread(() -> {
                try {
                    JSONObject b = new JSONObject(bodyJson == null ? "{}" : bodyJson);
                    String retailer = b.optString("retailer", ""), query = first(b.optString("upc", ""), b.optString("sku", ""), b.optString("title", ""), "tools");
                    Intent i = new Intent(activity, RetailerVerificationActivity.class);
                    i.putExtra(RetailerVerificationActivity.EXTRA_RETAILER, retailer); i.putExtra(RetailerVerificationActivity.EXTRA_QUERY, query);
                    i.putExtra(RetailerVerificationActivity.EXTRA_SOURCE_URL, b.optString("source_url", "")); i.putExtra(RetailerVerificationActivity.EXTRA_STORE, b.optString("store_address", b.optString("store_name", "")));
                    activity.startActivity(i);
                } catch (Exception ignored) {}
            });
        }
        private static String first(String... v) { for (String x : v) if (x != null && !x.trim().isEmpty()) return x.trim(); return ""; }
    }

