    private static WebView findWebView(View view) { if (view instanceof WebView) return (WebView) view; if (view instanceof ViewGroup) { ViewGroup g=(ViewGroup)view; for(int i=0;i<g.getChildCount();i++){WebView w=findWebView(g.getChildAt(i));if(w!=null)return w;}} return null; }
    private static String sharedText(Intent intent) { if (intent==null||!Intent.ACTION_SEND.equals(intent.getAction()))return null;String type=intent.getType();if(type!=null&&!type.startsWith("text/"))return null;String t=intent.getStringExtra(Intent.EXTRA_TEXT);if(t==null||t.trim().isEmpty())t=intent.getStringExtra(Intent.EXTRA_SUBJECT);return t==null||t.trim().isEmpty()?null:t.trim(); }
    private void inject(Activity activity) {
        if (!(activity instanceof MainActivity)) return;
        WebView webView = findWebView(activity.getWindow().getDecorView()); if (webView == null) return;
        webView.addJavascriptInterface(new Bridge(activity, webView), "AndroidH38Scout");
        String shared = sharedText(activity.getIntent());
        String js = PATCH_JS + (shared == null ? "" : "\nwindow.H38SharedOpportunity&&window.H38SharedOpportunity(" + JSONObject.quote(shared) + ");");
        webView.evaluateJavascript(js, null); if (shared != null) activity.getIntent().setAction(null);
    }
